              <div className="flex justify-between items-start mb-6">
                <span className="font-semibold text-lg text-gray-500">Giá xe giao dịch tại thị trường</span>
                <div className="flex items-center gap-2">
                  <div className="text-xs font-bold bg-orange-400 text-white px-2 py-0.5 rounded">oto<br/>.com</div>
                  <div className="text-xs font-bold text-blue-600 border border-blue-200 px-1 py-0.5 rounded">bonbanh</div>
                </div>
              </div>

              <div className="text-3xl font-extrabold text-[#1a2b49] mb-6">
                {valuationData.marketPrice}
